const THRESHOLD = 0.72;
const WINDOW_MS = 86400000;
const me = String($('Parse Question').first().json.customer_id).trim();
const now = Date.now();
const hits = $input.all().filter(i => i.json.document).map(i => ({
  customer: String(i.json.document.metadata.customer_id).trim(),
  score: i.json.score,
  text: i.json.document.pageContent,
  at: Number(i.json.document.metadata.asked_at)
})).filter(h => now - h.at <= WINDOW_MS);
const similar = hits.filter(h => h.score >= THRESHOLD);
const others = [...new Set(similar.map(h => h.customer).filter(c => c !== me && c !== 'UNKNOWN'))];
return [{ json: { threshold: THRESHOLD, window_hours: WINDOW_MS / 3600000, similar_count: similar.length, other_customers: others, distinct_customers: others.length + 1, summary: hits.map(h => h.customer + ' ' + h.score.toFixed(2) + ' ' + h.text.slice(0, 40)).join(' | '), hits } }];

