const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const o = $json.output || $json;
const raw = $('AI Agent').first().json.output || '';
const ev = norm(raw);
const ex = norm((raw.match(/excerpt[^\n]*/gi) || []).join(' '));
const stop = ['from', 'with', 'that', 'this', 'have', 'does'];
const words = norm(o.key_term).split(' ').filter(w => w.length > 3 && !stop.includes(w)).map(w => w.slice(0,6));
const parts = (o.supporting_evidence || '').split(/[.;]/).map(norm).filter(p => p.split(' ').length >= 4);
const quoteOk = parts.some(p => ev.includes(p));
const topicOk = words.length > 0 && words.some(w => ex.includes(w));
o.citations = (o.citations || []).filter(c => c.url && raw.includes(c.url));
o.debug = JSON.stringify({ k: words, quoteOk: quoteOk, topicOk: topicOk });
if (!(quoteOk && topicOk)) {
  o.notes = '';
  o.supporting_evidence = '';
  o.recommend_escalation = true;
  o.answer = 'The sources I searched do not mention "' + (o.key_term || 'this topic') + '", so I cannot confirm an answer. Recommend escalating to the Dev team.';
  o.confidence_reason = 'No source excerpt mentions the topic.';
  o.searched_sources = o.citations;
  o.citations = [];
}

if (o.recommend_escalation) { o.confidence = 'low'; }
return { json: o };

const card = $('Analyst Card').first().json;
const j = $json;
const reply = String(j.data?.text ?? j.text ?? j.response ?? j.chatInput ?? j.message ?? '').trim();
const low = reply.toLowerCase();
let decision = 'edit';
if (low === 'approve' || low === 'approved' || low === 'yes') decision = 'approve';
else if (low === 'escalate' || low === 'no') decision = 'escalate';
else if (!reply) decision = 'unclear';
return { json: {
  decision: decision,
  reply: reply,
  final_answer: decision === 'edit' ? reply : card.answer,
  question: card.question,
  customer_id: card.customer_id,
  ticket_key: card.ticket_key,
  route: card.route,
  distinct_customers: card.distinct_customers,
  debug_raw: JSON.stringify(j)
} };

const g = $json;
const t = $('Triage Guard').first().json;
const p = $('Parse Question').first().json;
const cites = (g.citations || []).map(c => c.label + ': ' + c.url);
const sources = g.ticket_url ? [g.ticket_url] : cites;
const esc = g.recommend_escalation !== undefined ? g.recommend_escalation : g.recommended_escalation;
const card = '**Draft answer** (confidence: ' + g.confidence + (esc ? ', escalation recommended' : '') + ')\n\n' + g.answer + '\n\n' + (g.notes ? '**Notes:** ' + g.notes + '\n\n' : '') + '**Sources:**\n' + (sources.length ? sources.join('\n') : 'None found') + '\n\nRoute: ' + t.route + (t.ticket_key ? ' (' + t.ticket_key + ')' : '') + ' | Similar reports in the last 24h: ' + t.distinct_customers;

return { json: {
  question: String(p.chatInput).trim(),
  customer_id: String(p.customer_id).trim(),
  asked_at: p.asked_at,
  route: t.route,
  ticket_key: t.ticket_key || '',
  closest_ticket: t.closest_ticket || '',
  distinct_customers: t.distinct_customers,
  answer: g.answer,
  confidence: g.confidence,
  recommend_escalation: esc,
  notes: g.notes || '',
  sources: (sources.length ? sources.join('\n') : 'None found'),
  card_text: card + (g.next_step ? '\n\n**Suggested next step:** ' + g.next_step : ''),
  orchestrator_decision: g.orchestrator_decision || ''
} };

const c = $('Analyst Card').first().json;
const n = Number(c.distinct_customers) || 1;
const q = String(c.question).replace(/\s+/g, ' ').trim();
const desc = [
  'h3. Escalated from the Support Copilot',
  '*Question:* ' + q,
  '*Customers reporting in the last 24h:* ' + n,
  '*Agent route:* ' + c.route + (c.closest_ticket ? ' (closest ticket considered: ' + c.closest_ticket + ')' : ''),
  '*Agent confidence:* ' + c.confidence,
  '*Agent draft answer:* ' + c.answer,
  '*Sources searched:* ' + (c.sources || 'none found'),
  '*Requested by:* support analyst (customer details intentionally omitted)'
].join('\n\n');
const payload = { fields: {
  project: { key: 'INV' },
  issuetype: { name: 'Task' },
  summary: ('Support escalation: ' + q).slice(0, 120),
  description: desc,
  labels: ['support-escalation', 'customer-impact']
} };
return { json: { payload } };

const c = $('Analyst Card').first().json;
const key = $json.key;
const q = String(c.question).replace(/\s+/g, ' ').trim();
const text = key + ' | Task | Support escalation: ' + q + '. Escalated by a support analyst; ' + (Number(c.distinct_customers) || 1) + ' customer(s) reported this in the last 24h. No workaround documented yet.';
return { json: {
  text: text,
  issue_key: key,
  issue_type: 'Task',
  status: 'To Do',
  priority: '',
  labels: 'support-escalation,customer-impact',
  parent_key: '',
  source_url: 'https://anshumancricket.atlassian.net/browse/' + key,
  updated: new Date().toISOString()
} };

const cur = $('Analyst Card').first().json;
const now = Date.now();
const rows = $input.all().filter(i => i.json.document).map(i => ({
  c: String(i.json.document.metadata.customer_id).trim(),
  at: Number(i.json.document.metadata.asked_at)
})).filter(r => now - r.at <= 86400000 && r.c !== 'UNKNOWN');
const all = new Set(rows.map(r => r.c));
all.add(String(cur.customer_id).trim());
const before = new Set(rows.filter(r => r.at < Number(cur.asked_at)).map(r => r.c));
const n = all.size;
return [{ json: { ticket_key: cur.ticket_key, affected: n, before: before.size, alert: n >= 3 && n > before.size } }];

