const o = $json.output || $json;
const g = $('Guard').first().json;
const retried = $runIndex >= 1;
let decision = o.decision || 'present';
if (decision === 'retry' && retried) { decision = 'escalate'; }
const out = Object.assign({}, g);
out.orchestrator_decision = decision;
out.orchestrator_reason = o.reason || '';
out.next_step = o.next_step || '';
out.retry_query = String(o.retry_query || '').split('\n')[0].slice(0, 150);
if (decision === 'escalate') {
  out.recommend_escalation = true;
  if (!g.supporting_evidence) { out.confidence = 'low'; }
}
return { json: out };
